from pathlib import Path
import json
root=Path(__file__).resolve().parent
js=(root/'source.js').read_text().replace('LETTERING_DATA',json.dumps(json.loads((root/'lettering.json').read_text()),ensure_ascii=False))
assert '</script' not in js.lower()
shell='''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>GET → KEEP / Running motion</title><style>
*{box-sizing:border-box}body{background:#102515;color:white;margin:0;font-family:Arial,Helvetica,sans-serif}main{max-width:1180px;padding:30px;margin:auto;min-height:100vh;display:grid;grid-template-columns:1fr minmax(0,460px);gap:60px;align-items:center}.eyebrow{font:11px monospace;letter-spacing:2px;color:#28d63f}h1{font-size:70px;line-height:.91;letter-spacing:-5px;margin:25px 0}h1 span{color:#28d63f}p{max-width:380px;line-height:1.65;font-size:15px;color:#c2cec4}.tags{display:flex;gap:9px;flex-wrap:wrap}.tag{border:1px solid #526c59;padding:8px;font:11px monospace}.stage{width:100%;aspect-ratio:9/16;background:white;box-shadow:0 25px 80px #0004;overflow:hidden}canvas{width:100%;height:100%;display:block}.controls{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin-top:17px;font:11px monospace}button{background:#28d63f;color:#102515;border:0;font:inherit;padding:13px 17px;cursor:pointer}label{display:flex;gap:5px;align-items:center}input{accent-color:#28d63f}input[type=range]{width:100%;margin-top:18px}output{margin-left:auto}a{color:#28d63f}button:focus-visible,input:focus-visible,a:focus-visible{outline:3px solid white;outline-offset:4px}.note{font:11px monospace;line-height:1.7}.sr{position:absolute;width:1px;height:1px;clip-path:inset(50%);overflow:hidden}@media(max-width:760px){main{display:flex;flex-direction:column;padding:20px;gap:25px;align-items:stretch}.player{width:100%;max-width:460px;align-self:center}h1{font-size:54px;margin:20px 0}.intro p{margin:16px 0}}
</style></head><body><main><section class="intro"><div class="eyebrow">PULSO / RUNNING MOTION 003</div><h1>GET.<br><span>KEEP.</span><br>RUNNING.</h1><p>Arrancar é o começo. Continuar é a escolha. Um motion de impacto inspirado no ritmo da corrida e no lettering enviado.</p><div class="tags"><span class="tag">10 SEGUNDOS</span><span class="tag">9:16</span><span class="tag">GET → KEEP / 5 S</span></div><p class="note">Lettering reconstruído em vetores a partir da referência raster. KEEP desenhado para acompanhar esse estilo. Sem áudio.</p><p><a href="../../index.html">← Run Culture</a> · <a href="../../assets/get-keep-running.mp4" download>Baixar MP4</a></p></section><section class="player"><div class="stage" id="stage"><canvas id="canvas" width="1080" height="1920" role="img" aria-label="Animação de dez segundos: GET RUNNING muda para KEEP RUNNING aos cinco segundos, com lettering verde arredondado e movimentos de aceleração."></canvas></div><div class="controls"><button id="play">Reproduzir</button><label><input type="checkbox" id="loop">Repetir</label><output id="time">0,0 / 10,0 s</output></div><input type="range" id="timeline" min="0" max="10000" step="1" value="0" aria-label="Posição da animação"><p class="sr" id="status" role="status">Pronto.</p></section></main><script>EMBED_SCRIPT</script></body></html>'''
(root/'index.html').write_text(shell.replace('EMBED_SCRIPT',js))
# Vector lettering proof; no embedded stock font outlines.
d=json.loads((root/'lettering.json').read_text());g=d['glyphs']
def word(s,x,y,width):
 total=sum(g[ch]['width'] for ch in s)+34*(len(s)-1);scale=width/total;parts=[];offset=0
 for ch in s:
  parts.append(f'<path d="{g[ch]["path"]}" transform="translate({x+offset*scale} {y}) scale({scale})"/>');offset+=g[ch]['width']+34
 return ''.join(parts)
svg='<svg xmlns="http://www.w3.org/2000/svg" width="1080" height="1920" viewBox="0 0 1080 1920"><rect width="1080" height="1920" fill="white"/><g fill="#28d63f" fill-rule="evenodd">'+word('KEEP',64,270,952)+word('RUN',64,685,952)+word('NING',83,1070,933)+'</g></svg>'
(root/'lettering-proof.svg').write_text(svg)
